'use strict';

// Generates the neutral theme-pack fixture in ./neutral-deck (run with node).
// The pack is invented test art: flat-coloured tiles, a chair, a rail and a
// one-body sprite sheet. Re-running it reproduces the committed files.

const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');

const OUT = path.join(__dirname, 'neutral-deck');

function crc32(buf) {
  let c, crc = 0xffffffff;
  for (let n = 0; n < buf.length; n++) {
    c = (crc ^ buf[n]) & 0xff;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    crc = (crc >>> 8) ^ c;
  }
  return (crc ^ 0xffffffff) >>> 0;
}
function chunk(type, data) {
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
  const td = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(td));
  return Buffer.concat([len, td, crc]);
}
/** RGBA pixels -> PNG bytes. */
function png(w, h, rgba) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr[8] = 8; ihdr[9] = 6; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;
  const raw = Buffer.alloc((w * 4 + 1) * h);
  for (let y = 0; y < h; y++) { raw[y * (w * 4 + 1)] = 0; Buffer.from(rgba.buffer, y * w * 4, w * 4).copy(raw, y * (w * 4 + 1) + 1); }
  return Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), chunk('IHDR', ihdr), chunk('IDAT', zlib.deflateSync(raw)), chunk('IEND', Buffer.alloc(0))]);
}
function canvas(w, h) {
  const d = new Uint8Array(w * h * 4);
  return { w, h, d, rect(x0, y0, x1, y1, [r, g, b]) { for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) { const i = (y * w + x) * 4; d[i] = r; d[i + 1] = g; d[i + 2] = b; d[i + 3] = 255; } } };
}

// tiles.png: 4×2 tiles of 16 px. 0 floor, 1 wall, 2 rail (a bar on rows 8-11), 3 desk (rows 4-15),
// 4 marker (left half red, right half blue: shows flips)
const T = canvas(64, 32);
T.rect(0, 0, 16, 16, [100, 100, 110]);
T.rect(16, 0, 32, 16, [40, 40, 50]);
T.rect(32, 8, 48, 12, [200, 180, 60]);
T.rect(48, 4, 64, 16, [120, 80, 40]);
T.rect(0, 16, 8, 32, [220, 40, 40]); T.rect(8, 16, 16, 32, [40, 40, 220]);
// chair.png (a collection tile): backrest rows 2-5, seat rows 8-13
const C = canvas(16, 16);
C.rect(4, 2, 12, 6, [60, 120, 200]); C.rect(3, 8, 13, 14, [60, 120, 200]);
// sheet.png: 2 bodies (columns) × 8 rows of 32 px frames; a body is a block, rows 4-31, cols 10-21
const S = canvas(64, 256);
for (let row = 0; row < 8; row++) { S.rect(10, row * 32 + 4, 22, row * 32 + 32, [230, 200, 160]); S.rect(42, row * 32 + 4, 54, row * 32 + 32, [90, 60, 40]); }

const W = 12, H = 10, gidFloor = 1, gidWall = 2, gidRail = 3, gidDesk = 4, gidMark = 5, gidChair = 9, FLIP_H = 0x80000000;
const floor = [], walls = [], rail = [];
for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
  floor.push(y === 0 ? 0 : y === 9 && x === 0 ? (gidMark | FLIP_H) >>> 0 : gidFloor);
  walls.push(y === 0 ? gidWall : 0);
  rail.push(y === 6 && x >= 2 && x <= 9 ? gidRail : 0);
}
const csv = (a) => a.map(String).join(',');

const props = [
  { id: 10, name: 'desk-a', gid: gidDesk, x: 32, y: 48, w: 16, h: 16 },
  { id: 11, name: 'chair-a', gid: gidChair, x: 32, y: 64, w: 16, h: 16 },
  { id: 12, name: 'desk-b', gid: gidDesk, x: 112, y: 48, w: 16, h: 16 },
  { id: 13, name: 'chair-b', gid: gidChair, x: 112, y: 64, w: 16, h: 16 },
  { id: 14, name: 'chair-c', gid: gidChair, x: 32, y: 144, w: 16, h: 16 },
];
const points = [
  { id: 20, name: 'Spawn', x: 96, y: 140 },
  { id: 21, name: 'Alpha', x: 40, y: 58, facing: 'up' },
  { id: 22, name: 'Beta', x: 120, y: 58, facing: 'up' },
  { id: 23, name: 'Gamma', x: 40, y: 138 },
  { id: 24, name: 'Lounge', x: 150, y: 90 },
  { id: 25, name: 'Coffee', x: 168, y: 80 },
];
// where each station's mug is parked (coffee.mugLayer): on the desks, and beside Gamma's chair
const mugs = [
  { id: 26, name: 'Alpha', x: 44, y: 52 },
  { id: 27, name: 'Beta', x: 124, y: 52 },
  { id: 28, name: 'Gamma', x: 52, y: 146 },
];

const tmx = `<?xml version="1.0" encoding="UTF-8"?>
<!-- neutral fixture: generated by make-neutral-deck.cjs -->
<map version="1.10" tiledversion="1.11.2" orientation="orthogonal" renderorder="right-down" width="${W}" height="${H}" tilewidth="16" tileheight="16" infinite="0" nextlayerid="10" nextobjectid="30">
 <tileset firstgid="1" source="tiles/tiles.tsx"/>
 <tileset firstgid="9" source="C:\\Users\\someone\\art\\props.tsx"/>
 <imagelayer id="8" name="reference" visible="1">
  <image source="tracing.png" width="192" height="160"/>
 </imagelayer>
 <layer id="1" name="Floor" width="${W}" height="${H}">
  <data encoding="csv">${csv(floor)}</data>
 </layer>
 <layer id="2" name="Walls" width="${W}" height="${H}">
  <data encoding="csv">${csv(walls)}</data>
 </layer>
 <layer id="3" name="Rail" width="${W}" height="${H}">
  <data encoding="csv">${csv(rail)}</data>
 </layer>
 <objectgroup id="4" name="collision-shapes" visible="1">
  <object id="1" name="rail-guard" x="32" y="104" width="128" height="4"/>
  <object id="2" name="corner" x="160" y="128">
   <polygon points="0,0 32,0 32,32"/>
  </object>
 </objectgroup>
 <objectgroup id="5" name="Props">
${props.map((p) => `  <object id="${p.id}" name="${p.name}" gid="${p.gid}" x="${p.x}" y="${p.y}" width="${p.w}" height="${p.h}"/>`).join('\n')}
 </objectgroup>
 <objectgroup id="6" name="Stations" visible="0">
${points.map((p) => `  <object id="${p.id}" name="${p.name}" x="${p.x}" y="${p.y}">${p.facing ? `\n   <properties>\n    <property name="facing" value="${p.facing}"/>\n   </properties>\n   <point/>\n  </object>` : '\n   <point/>\n  </object>'}`).join('\n')}
 </objectgroup>
 <objectgroup id="9" name="Mugs" visible="0">
${mugs.map((p) => `  <object id="${p.id}" name="${p.name}" x="${p.x}" y="${p.y}">\n   <point/>\n  </object>`).join('\n')}
 </objectgroup>
</map>
`;
const tilesTsx = `<?xml version="1.0" encoding="UTF-8"?>
<tileset version="1.10" tiledversion="1.11.2" name="tiles" tilewidth="16" tileheight="16" tilecount="8" columns="4">
 <image source="tiles.png" width="64" height="32"/>
</tileset>
`;
const propsTsx = `<?xml version="1.0" encoding="UTF-8"?>
<tileset version="1.10" tiledversion="1.11.2" name="props" tilewidth="16" tileheight="16" tilecount="1" columns="0">
 <grid orientation="orthogonal" width="1" height="1"/>
 <tile id="0">
  <image source="pictures/chair.png" width="16" height="16"/>
 </tile>
</tileset>
`;
// the same map as Tiled JSON (external tilesets as .tsj)
const tmj = {
  type: 'map', version: '1.10', orientation: 'orthogonal', renderorder: 'right-down', width: W, height: H, tilewidth: 16, tileheight: 16, infinite: false,
  tilesets: [{ firstgid: 1, source: 'tiles/tiles.tsj' }, { firstgid: 9, source: 'props.tsj' }],
  layers: [
    { id: 8, name: 'reference', type: 'imagelayer', image: 'tracing.png', visible: true, opacity: 1, x: 0, y: 0 },
    { id: 1, name: 'Floor', type: 'tilelayer', width: W, height: H, data: floor, visible: true, opacity: 1, x: 0, y: 0 },
    { id: 2, name: 'Walls', type: 'tilelayer', width: W, height: H, data: walls, visible: true, opacity: 1, x: 0, y: 0 },
    { id: 3, name: 'Rail', type: 'tilelayer', width: W, height: H, data: rail, visible: true, opacity: 1, x: 0, y: 0 },
    { id: 4, name: 'collision-shapes', type: 'objectgroup', visible: true, opacity: 1, x: 0, y: 0, objects: [
      { id: 1, name: 'rail-guard', x: 32, y: 104, width: 128, height: 4, rotation: 0, visible: true },
      { id: 2, name: 'corner', x: 160, y: 128, width: 0, height: 0, rotation: 0, visible: true, polygon: [{ x: 0, y: 0 }, { x: 32, y: 0 }, { x: 32, y: 32 }] },
    ] },
    { id: 5, name: 'Props', type: 'objectgroup', visible: true, opacity: 1, x: 0, y: 0, objects: props.map((p) => ({ id: p.id, name: p.name, gid: p.gid, x: p.x, y: p.y, width: p.w, height: p.h, rotation: 0, visible: true })) },
    { id: 6, name: 'Stations', type: 'objectgroup', visible: false, opacity: 1, x: 0, y: 0, objects: points.map((p) => ({
      id: p.id, name: p.name, x: p.x, y: p.y, width: 0, height: 0, rotation: 0, visible: true, point: true,
      ...(p.facing ? { properties: [{ name: 'facing', type: 'string', value: p.facing }] } : {}) })) },
    { id: 9, name: 'Mugs', type: 'objectgroup', visible: false, opacity: 1, x: 0, y: 0, objects: mugs.map((p) => ({
      id: p.id, name: p.name, x: p.x, y: p.y, width: 0, height: 0, rotation: 0, visible: true, point: true })) },
  ],
};
const tilesTsj = { type: 'tileset', name: 'tiles', tilewidth: 16, tileheight: 16, tilecount: 8, columns: 4, image: 'tiles.png', imagewidth: 64, imageheight: 32 };
const propsTsj = { type: 'tileset', name: 'props', tilewidth: 16, tileheight: 16, tilecount: 1, columns: 0, tiles: [{ id: 0, image: 'pictures/chair.png', imagewidth: 16, imageheight: 16 }] };

const manifest = {
  $comment: 'Neutral test pack (invented art). Generated by make-neutral-deck.cjs.',
  schema: 1,
  id: 'neutral-deck',
  label: 'Neutral Deck',
  sceneKind: 'stations',
  map: 'deck.tmx',
  palette: { background: '#101418' },
  stations: {
    layer: 'Stations',
    entrance: 'Spawn',
    captain: 'Alpha',
    seatOrder: ['Alpha', 'Beta', 'Gamma'],
    exclude: ['Lounge'],
    seats: { Gamma: { facing: 'right', role: 'ops' } },
  },
  navigation: { walkGrid: 4 },
  coffee: { brew: ['Coffee'], mugLayer: 'Mugs', cooldown: [180, 300] },
  spriteRenderer: {
    kind: 'sheet', sheet: 'pictures/sheet.png', frameWidth: 32, frameHeight: 32,
    rows: { down: 0, up: 1, left: 4, right: 6, sitDown: 2, sitUp: 3, sitLeft: 5, sitRight: 7 },
  },
  builder: {
    bodies: [{ id: 'light', label: 'Light', column: 0 }, { id: 'dark', label: 'Dark', column: 1 }],
    presets: [{ id: 'pilot', label: 'Pilot', bodyId: 'dark', seat: 'Beta' }],
  },
  projectDefaults: { orchestrator: { name: 'Lead', appearance: { bodyId: 'light' } } },
};

fs.mkdirSync(path.join(OUT, 'tiles'), { recursive: true });
fs.mkdirSync(path.join(OUT, 'pictures'), { recursive: true });
const write = (p, data) => fs.writeFileSync(path.join(OUT, p), data);
write('theme.json', JSON.stringify(manifest, null, 2) + '\n');
write('deck.tmx', tmx);
write('deck.tmj', JSON.stringify(tmj, null, 1) + '\n');
write('tiles/tiles.tsx', tilesTsx);
write('tiles/tiles.tsj', JSON.stringify(tilesTsj, null, 1) + '\n');
write('tiles/tiles.png', png(T.w, T.h, T.d));
write('props.tsx', propsTsx);
write('props.tsj', JSON.stringify(propsTsj, null, 1) + '\n');
write('pictures/chair.png', png(C.w, C.h, C.d));
write('pictures/sheet.png', png(S.w, S.h, S.d));
